WFJ.Data.add("spell", {
  [1002] = { "Prendi il controllo diretto del tuo famiglio e osserva attraverso i suoi occhi per $D1.", "Controllo diretto del famiglio.", 0xd5cd7f27, 0x2553e1fb, "uu" },
  [1003] = { "Ti insegna l'abilità Shadow Word: Befuddle (Grado $N1).", nil, 0x93c39130, nil, "um" },
  [1004] = { "Punisce un nemico infliggendo $N1 danni da sacro.", nil, 0x05e38ce8, nil, "um" },
  [1006] = { "Un'esplosione di energia sacra pervade l'incantatore, aumentando l'Armatura di $N1. Ogni colpo in mischia o a distanza che infligge danni al Sacerdote rimuove una carica. Dura $D1 o finché non vengono usate $N3 cariche.", "Armatura aumentata di $N1.", 0x92b16b08, 0xa12ba50b, "uu" },
  [1008] = { "Amplifica la magia usata contro il membro del gruppo bersaglio, aumentando fino a $N1 i danni subiti dagli incantesimi e fino a $N2 le cure ricevute dagli incantesimi. Dura $D1.", "Danni magici subiti aumentati fino a $N1 e cure ricevute aumentate fino a $N2.", 0xfcbd4f5d, 0x129e5d1f, "uu" },
  [1010] = { "Maledice il bersaglio con l'idiozia, riducendo Intelletto e Spirito di $N1 ogni $N2 s fino a una riduzione totale di $N3 per ciascuno. Su un bersaglio può essere attiva solo una maledizione per Stregone alla volta.", "Intelletto e Spirito ridotti.", 0x0a44f5ea, 0xe75db6a0, "uu" },
  [1014] = { "Affligge il bersaglio con l'agonia, infliggendo $N1 danni da ombra in $D1. All'inizio i danni sono inflitti lentamente e aumentano man mano che l'anatema si avvicina alla sua durata massima. Su un bersaglio può essere attivo solo un anatema per Stregone alla volta.", { "$N1 danni da ombra in $D1.", shape = { "2/1" } }, 0xd5b9a42b, 0x0adb28cc, "uu" },
  [1020] = { "Protegge il Paladino da tutti i danni e gli incantesimi per $D1, ma riduce del $N2% tutti i danni che infliggi. Applica Rigorosità per $D2. Non può essere lanciato mentre Rigorosità è attiva.", "Immune ad attacchi e incantesimi, ma tutti i danni che infliggi sono ridotti del $N1%.", 0x0bcdb662, 0x69b0b050, "uu" },
  [1022] = { "Protegge un membro del gruppo bersaglio da tutti gli attacchi fisici per $D1, ma in questo lasso di tempo non può attaccare né usare abilità fisiche. Il bersaglio alleato può ricevere solo una Benedizione per Paladino alla volta. Applica Rigorosità per $D2. Non può essere lanciato mentre Rigorosità è attiva.", "Immune agli attacchi fisici. Impossibile attaccare o usare abilità fisiche.", 0x272021e3, 0x3445333b, "uu" },
  [1023] = { "Ti insegna l'abilità ⟦Seal of Protection=Sigillo di Protezione⟧ (Grado $N1).", nil, 0x12c01864, nil, "um" },
  [1026] = { "Cura un bersaglio alleato di $N1.", nil, 0xbe4c0f4a, nil, "um" },
  [1027] = { "Ti insegna l'abilità ⟦Holy Light=Luce Sacra⟧ (Grado $N1).", nil, 0x4ef0705b, nil, "um" },
  [1029] = { "Ti insegna l'abilità Bane of Agony (Grado $N1).", nil, 0x403175aa, nil, "um" },
  [1032] = { "Fornisce $N1 Armatura aggiuntiva ai membri del gruppo entro $N2 m. Il bersaglio alleato può ricevere solo un'Aura per Paladino alla volta.", "Armatura aumentata di $N1.", 0xc600442a, 0xa12a98e7, "uu" },
  [1037] = { "Ti insegna l'abilità Seal of Fury (Grado $N1).", nil, 0x00ddca40, nil, "um" },
  [1038] = { "Riduce del $N1% tutta la minaccia generata dal membro del gruppo bersaglio per $D1.", "Minaccia generata ridotta del $N1%.", 0xf71ac83a, 0x69005136, "uu" },
  [1042] = { "Cura un bersaglio alleato di $N1.", nil, 0xbe4c0f4a, nil, "um" },
  [1044] = { "Piazza una Benedizione sul bersaglio alleato, fornendo immunità agli effetti di limitazione al movimento per $D1. Il bersaglio alleato può ricevere solo una Benedizione per Paladino alla volta.", "Immune agli effetti di limitazione al movimento.", 0x25b79994, 0xfedffc69, "uu" },
  [1058] = { "Cura il bersaglio di $N1 in $D1.", "Cura di $N1 ogni $N2 s.", 0x3367b9a9, 0x1302c045, "uu" },
  [1062] = { { "Immobilizza il bersaglio e gli infligge $N1 danni da natura in $D1. I danni subiti possono interrompere l'effetto. Puoi immobilizzare fino a $N3 bersagli alla volta.", "Immobilizza il bersaglio e gli infligge $N1 danni da natura in $D1. I danni subiti possono interrompere l'effetto. Puoi immobilizzare solo 1 bersaglio alla volta.", shape = { "3/1", "3/1" } }, "Immobilizzato. $N1 danni da natura subiti ogni $D1.", 0x72d7ae6f, 0x6c03815b, "uu" },
  [1064] = { "Cura il bersaglio alleato di $N1, poi passa a curare altri bersagli vicini. Se lanciata su un membro del gruppo, la cura passa solo ad altri membri del gruppo. Ogni passaggio è efficace al $N2% rispetto al bersaglio precedente. Cura $N3 bersagli in totale.", nil, 0xa9f16400, nil, "um" },
  [1066] = { "Assume la ⟦Aquatic Form=Forma Acquatica⟧, aumentando la velocità di nuoto del $N1% e permettendo al Druido di respirare sott'acqua. Inoltre protegge l'incantatore dagli effetti di metamorfosi.\n\nIl cambio di forma libera l'incantatore dagli effetti di metamorfosi e di limitazione al movimento.", "Immune agli effetti di metamorfosi. Velocità di nuoto aumentata del $N1% e respirazione subacquea.", 0x9793d095, 0x11a64bd1, "uu" },
  [1070] = { "Ti insegna l'abilità ⟦Faerie Fire=Fuoco Fatato⟧ (Grado $N1).", nil, 0xbe93bd35, nil, "um" },
  [1075] = { "Delle spine fuoriescono dal bersaglio alleato, infliggendo $N1 danni da natura agli attaccanti quando colpiscono. Dura $D1.", "Infligge $N1 danni da natura agli attaccanti.", 0xda837ee9, 0x763a853a, "uu" },
  [1079] = { "Mossa risolutiva che infligge danni nel tempo. I danni aumentano con ogni punto combo e con la potenza d'attacco:\n $N1 punto: $N2 danni in $D1.\n $N4 punti: $N5 danni in $D2.\n $N7 punti: $N8 danni in $D3.\n $N10 punti: $N11 danni in $D4.\n $N13 punti: $N14 danni in $D5.", "$N1 danni da sanguinamento ogni $D1.", 0x49157ab0, 0x75c83da5, "uu" },
  [1082] = { "Sfregia il nemico, infliggendo il $N1% dei danni normali più $N2. Fornisce $N3 punti combo.", nil, 0x93d55dee, nil, "um" },
  [1084] = { "Travolge il bersaglio, infliggendo $N1 danni da fuoco.", nil, 0x9d8bd0af, nil, "um" },
  [1086] = { "Protegge l'incantatore, aumentando l'Armatura di $N1 e la resistenza all'ombra di $N2 e rigenerando $N3 salute in più ogni $D1 per $D2.", "Armatura aumentata di $N1, resistenza all'ombra aumentata di $N2 e $N3 salute in più rigenerata ogni $D1.", 0x6ab340ac, 0x91ee7074, "uu" },
  [1088] = { "Lancia un dardo d'ombra contro il nemico, infliggendo $N1 danni da ombra.", nil, 0xc6f8d47d, nil, "um" },
  [1089] = { "Ti insegna l'abilità ⟦Shadow Bolt=Dardo d'Ombra⟧ (Grado $N1).", nil, 0x19e1b0c9, nil, "um" },
  [1090] = { "Costringe il bersaglio nemico a dormire per un massimo di $D1. Eventuali danni inflitti al bersaglio interrompono l'effetto. Può essere addormentato solo un bersaglio alla volta.", "Addormentato.", 0x26124111, 0x5339954e, "uu" },
  [1094] = { "Brucia il nemico, infliggendo $N1 danni da fuoco e altri $N2 danni da fuoco in $D1.", "$N1 danni da fuoco ogni $N2 s.", 0xe3931f57, 0x0d35ca56, "uu" },
  [1096] = { "Travolge il bersaglio, infliggendo $N1 danni da fuoco.", nil, 0x9d8bd0af, nil, "um" },
  [1098] = { "Soggioga il demone bersaglio, fino al livello $N1, costringendolo a eseguire i tuoi ordini. Mentre è soggiogato, l'intervallo tra gli attacchi del demone aumenta del $N2% e la sua velocità di lancio d'incantesimi si riduce del $N3%. Dura fino a $D1. Se soggioghi ripetutamente lo stesso demone, diventerà più difficile da controllare a ogni tentativo.", "Assoggettato.", 0x93ce24f8, 0xb260b47a, "uu" },
  [1101] = { "Ti insegna l'abilità Mana Funnel.", nil, 0x293f7e68, nil, "um" },
  [1105] = { "Ti insegna l'abilità Seal of Wisdom (Grado $N1).", nil, 0x473624dc, nil, "um" },
  [1106] = { "Lancia un dardo d'ombra contro il nemico, infliggendo $N1 danni da ombra.", nil, 0xc6f8d47d, nil, "um" },
  [1107] = { "Ti insegna l'abilità Corruzione (Grado $N1).", nil, 0x0fd40525, nil, "um" },
  [1108] = { "I danni fisici inflitti dal bersaglio sono ridotti di $N1 per $D1. Su un bersaglio può essere attiva solo una maledizione per Stregone alla volta.", "Danni fisici inflitti ridotti di $N1.", 0x45b27a1b, 0x21281ce3, "uu" },
  [1109] = { "Ti insegna l'abilità ⟦Curse of Weakness=Maledizione di Debolezza⟧ (Grado $N1).", nil, 0xb223b388, nil, "um" },
  [1120] = { "Risucchia l'anima del bersaglio, infliggendo $N1 danni da ombra in $D1. I bersagli non banali danneggiati da Risucchio d'Anima hanno una probabilità di conferirti un frammento d'anima. I bersagli non banali uccisi da Risucchio d'Anima ti conferiscono sempre un frammento d'anima. I frammenti d'anima sono necessari per altri incantesimi.", "$N1 danni da ombra ogni $N2 s.", 0x0ad8031e, 0x774bc67a, "uu" },
  [1122] = { "Evoca una meteora dalla ⟦Twisting Nether=Distorsione Fatua⟧, che infligge $N1 danni da fuoco e stordisce tutti i nemici nell'area per $D1. Dal cratere sorge un infernale, agli ordini dell'incantatore per $D2. Una volta perso il controllo, l'infernale deve essere soggiogato per mantenerne il controllo. Utilizzabile solo all'aperto.", nil, 0x5a6ba85a, nil, "um" },
  [1126] = { "Aumenta l'Armatura del bersaglio alleato di $N1 per $D1.", "Armatura aumentata di $N1.", 0xfb7f6b76, 0xa12a98e7, "uu" },
  [1127] = { "Rigenera $N1 salute in $D1. Devi sederti per mangiare.", "$N1 salute rigenerata ogni secondo.", 0xe5e04206, 0xfde4540f, "uu" },
  [1129] = { "Rigenera $N1 salute in $D1. Devi sederti per mangiare.", "$N1 salute rigenerata ogni secondo.", 0xe5e04206, 0xfde4540f, "uu" },
  [1130] = { "Applica il ⟦Hunter's Mark=Marchio del Cacciatore⟧ al bersaglio, aumentando di $N1 la potenza d'attacco a distanza di tutti gli attaccanti contro quel bersaglio. Inoltre, il bersaglio di questa abilità resta sempre visibile al Cacciatore, anche se diventa furtivo o invisibile. Il bersaglio appare anche sulla minimappa. Dura $D1.", "Tutti gli attaccanti ottengono $N1 potenza d'attacco a distanza contro questo bersaglio.", 0xf034dbfd, 0x3d2d7958, "uu" },
  [1131] = { "Rigenera $N1 salute in $D1. Devi sederti per mangiare.", "$N1 salute rigenerata ogni secondo.", 0xe5e04206, 0xfde4540f, "uu" },
