  [1138] = { "Aumenta la resistenza al gelo e all'ombra di $N1 per $D1.", "Resistenza al gelo e all'ombra aumentata.", 0xc31c32d3, 0x2ca18795, "uu" },
  [1139] = { "Aumenta l'intervallo tra gli attacchi del bersaglio del $N1% e ne riduce la velocità di movimento del $N2% per $D1.", "Velocità d'attacco ridotta del $N1%.\nVelocità di movimento ridotta del $N2%.", 0x8cbf1cf8, 0x3b8ba8d2, "uu" },
