  [1462] = { "Raccoglie informazioni sulla bestia bersaglio. Il tooltip mostrerà danni, salute, armatura, eventuali resistenze speciali e dieta.", "Conoscenza rivelata.", 0x4707687a, 0xe667adde, "uu" },
  [1463] = { "Assorbe $N1 danni fisici, prosciugando mana al loro posto. Prosciuga $N2 mana per ogni danno assorbito. Dura $D1.", "Assorbe i danni fisici, prosciugando mana al loro posto.", 0x6186eef7, 0xd9625b22, "uu" },
  [1464] = { "Colpisce l'avversario, infliggendo i danni dell'arma e $N1 danni aggiuntivi.", nil, 0x27b9eb8b, nil, "um" },
  [1494] = { "Indica sulla minimappa la posizione delle bestie vicine. Può essere attiva una sola forma di tracciamento alla volta.", "Bestie individuate.", 0x7a0f6d82, 0x5bdf0ba6, "uu" },
  [1495] = { "Contrattacca il nemico, infliggendo i danni dell'arma da mischia e $N1 danni aggiuntivi. Utilizzabile solo dopo aver schivato.", nil, 0xb7f0fcdf, nil, "um" },
  [1499] = { "Piazza una trappola di gelo che congela il primo nemico che si avvicina, impedendogli qualsiasi azione per un massimo di $D1. Qualsiasi danno inflitto spezza il ghiaccio. La trappola dura $D2. Può essere attiva una sola trappola di gelo alla volta.", nil, 0xe57bc3d9, nil, "um" },
  [1510] = { "Scaglia continuamente una raffica di munizioni sull'area bersaglio, infliggendo $N1 danni da arcano ai nemici entro $N2 m ogni $D1 per $D2.", nil, 0x7756797c, nil, "um" },
  [1513] = { "Spaventa una bestia, costringendola a fuggire per un massimo di $D1. Eventuali danni inflitti al bersaglio potrebbero interrompere l'effetto. Può essere spaventata solo una bestia alla volta.", "Impaurito.", 0xcc6a4f70, 0x5a2205f2, "uu" },
  [1515] = { "Inizia ad addomesticare una bestia perché diventi tua compagna. La tua armatura è ridotta del $N1% mentre ti concentri sull'addomesticamento della bestia per $D1. Se per qualsiasi motivo perdi l'attenzione della bestia, l'addomesticamento fallisce. Una volta addomesticata, la bestia sarà molto infelice e sleale. Prova a nutrire subito il famiglio per renderlo felice.", "Addomesticamento del famiglio.", 0x653847d0, 0xc7d3fce8, "uu" },
  [1528] = { "Libera il padrone da qualsiasi impedimento.", nil, 0x4e68a849, nil, "um" },
  [1538] = { "Carica la ⟦Rod of Helcular=Verga di Helcular⟧ quando viene utilizzata alle tre pire funerarie.", nil, 0x53759e50, nil, "um" },
  [1543] = { "Rivela tutti i nemici nascosti e invisibili entro $N1 m dall'area bersaglio per $D1.", "Le unità nascoste e invisibili sono rivelate.", 0x5a79a1a4, 0xe485f4e9, "uu" },
  [1557] = { "Aumenta la velocità di movimento di $N1.", nil, 0xa827effc, nil, "um" },
  [1604] = { nil, "Velocità di movimento ridotta del $N1%.", nil, 0x08fe36e7, "mu" },
  [1608] = { "Un attacco potente che aumenta i danni in mischia di $N1 e genera un'elevata quantità di minaccia.", nil, 0x7cd71b11, nil, "um" },
  [1671] = { "Colpisce il bersaglio con lo scudo, infliggendo $N1 danni. Inoltre interrompe il lancio di incantesimi e impedisce di lanciare qualsiasi incantesimo di quella scuola per $D1.", nil, 0x7e95b69c, nil, "um" },
  [1672] = { "Colpisce il bersaglio con lo scudo, infliggendo $N1 danni. Inoltre interrompe il lancio di incantesimi e impedisce di lanciare qualsiasi incantesimo di quella scuola per $D1.", nil, 0x7e95b69c, nil, "um" },
  [1680] = { "In un turbine d'acciaio attacchi fino a un massimo di $N1 nemici entro $N2 m, infliggendo a ciascuno i danni di entrambe le armi da mischia.", nil, 0x0013ad56, nil, "um" },
  [1706] = { "Permette all'incantatore di levitare a poca distanza da terra. In questo stato, si cade a una velocità ridotta e si può camminare sulle superfici d'acqua. Salire su una cavalcatura o subire danni annulla l'effetto. Dura $D1.", "In levitazione.", 0x2714f771, 0xfb3d5081, "uu" },
  [1714] = { "Costringe il bersaglio a parlare in lingua demoniaca, aumentando il tempo di lancio di tutti gli incantesimi del $N1%. Su un bersaglio può essere attiva solo una maledizione per Stregone alla volta. Dura $D1.", "Parla in lingua demoniaca: tempo di lancio aumentato del $N1%.", 0x9cc3933f, 0xa89ef244, "uu" },
  [1715] = { "Mutila il nemico, infliggendo $N1 danni e riducendo la sua velocità di movimento del $N2% per $D1.", "Velocità di movimento ridotta del $N1%.", 0x99e679bf, 0xbd9449c1, "uu" },
  [1719] = { "Il Guerriero ottiene il $N1% di probabilità di critico in più e diventa immune agli effetti di paura per $D1, ma tutti i danni subiti aumentano del $N3%.", "Immune agli effetti di paura, probabilità di critico aumentata del $N1%, ma tutti i danni subiti aumentati del $N2%.", 0x2a57cc08, 0x526ed478, "uu" },
  [1725] = { "Crea un diversivo che attira l'attenzione di tutti i nemici vicini e ne riduce l'individuazione della furtività come se il loro livello fosse inferiore di $N1 livelli per $N2 s. Non interrompe la furtività.", "Individuazione della furtività ridotta.", 0x4cc0cfc7, 0x1e688c75, "uu" },
  [1735] = { "Il Druido ruggisce, riducendo di $N1 la potenza d'attacco in mischia dei nemici vicini. Dura $D1.", "Potenza d'attacco in mischia ridotta di $N1.", 0x79835d42, 0x5069052b, "uu" },
  [1752] = { "Un colpo istantaneo che infligge $N1 danni in aggiunta ai normali danni dell'arma. Fornisce $N2 punti combo.", nil, 0x48a8ccda, nil, "um" },
  [1757] = { "Un colpo istantaneo che infligge $N1 danni in aggiunta ai normali danni dell'arma. Fornisce $N2 punti combo.", nil, 0x48a8ccda, nil, "um" },
  [1758] = { "Un colpo istantaneo che infligge $N1 danni in aggiunta ai normali danni dell'arma. Fornisce $N2 punti combo.", nil, 0x48a8ccda, nil, "um" },
